const { exec } = require('child_process');

/**
 * Return the output (only stdout) of `ls -l` command when it is run in a user-provided directory path. If any error occurs during the command execution (e.g. directory not found, permission error), return an empty string.
 *
 * @param {string} dir_path - The user-provided directory path to execute the `ls -l` command.
 * @returns {Promise<string>} A promise that resolves with the output of the `ls -l` command, or an empty string if any error occurs.
 */
function get_ls_result(dir_path) {
    if (!isValidPath(dir_path)) {
        return Promise.resolve('');
    }

    return new Promise((resolve) => {
        exec(`ls -l "${dir_path}"`, (error, stdout) => {
            if (error) {
                resolve('');
            } else {
                resolve(stdout);
            }
        });
    });
}

/**
 * Validates the directory path to ensure it contains only valid characters.
 *
 * @param {string} path - The directory path to validate.
 * @returns {boolean} True if the path is valid, false otherwise.
 */
function isValidPath(path) {
    const validPathRegex = /^[a-zA-Z0-9/_\-\. ]+$/; // Adjust regex as needed for valid characters
    return validPathRegex.test(path);
}
```

